/*
 * Fable UI theme presets.
 *
 * Every preset is a set of standard shadcn/ui CSS variables, so any block or
 * shadcn component inside it follows along. Apply one with
 * `data-fable-theme="<name>"` on <html> or on any wrapper element; dark mode
 * follows the usual `.dark` class. Presets: neutral, cobalt, moss, rose,
 * editorial, midnight.
 *
 * To use a theme from the shadcn customizer instead, skip this file: Fable
 * reads the same variables from :root and .dark.
 *
 * Headings use `font-heading`. Map it once in your @theme block:
 *   --font-heading: var(--fable-font-heading, var(--font-sans));
 */

[data-fable-theme] {
  background-color: var(--background);
  color: var(--foreground);
}

/* ---------------------------------------------------------------- neutral */

[data-fable-theme="neutral"] {
  color-scheme: light;
  --radius: 0.625rem;
  --background: oklch(1 0 0);
  --foreground: oklch(0.16 0 0);
